import LeanFM.Session.Syntax

/-- What the client orders. -/
structure CreateOrder where
  item : String
  quantity : Nat

/-- The shop's price for the order, in cents. -/
structure Quote where
  price : Nat

/-- The client pays; the card number is a secret, never logged. -/
structure Pay where
  amount : Nat
  card_secr : String

structure Charge where
  amount : Nat
  card_secr : String

structure Receipt where
  amount : Nat

/-- What is required: the conversation between a client, a shop and a bank, message by message. -/
protocol PlaceOrder (Client, Shop, Bank) {
  o: CreateOrder from Client to Shop route "POST /orders";
  choice {
    q: Quote from Shop to Client cause o status 201;
    p: Pay from Client to Shop cause q where p.amount = q.price;
    c: Charge from Shop to Bank cause p;
    choice {
      d: Charged from Bank to Shop cause c;
      Receipt from Shop to Client cause d status 200;
    } or {
      x: Declined from Bank to Shop cause c;
      PaymentDeclined from Shop to Client cause x status 402;
    }
  } or {
    SoldOut from Shop to Client cause o status 409;
  }
}

requirements {
  "Orders are placed as PlaceOrder says" => PlaceOrder;
  "Every order is answered" => PlaceOrder ⊨ (AG (implies (after CreateOrder) (AF (or (after Receipt) (after PaymentDeclined) (after SoldOut)))));
  "Every payment is charged to the bank" => PlaceOrder ⊨ (AG (implies (after Pay) (AF (after Charge))));
  "No receipt without a charge" => PlaceOrder ⊨ (not (EU (not (after Charged)) (after Receipt)));
  "A sold-out order is never charged" => PlaceOrder ⊨ (AG (implies (after SoldOut) (AG (not (after Charge)))));
  "Refunds within 30 days" => sorry "PlaceOrder has no Refund message yet";
}

impl:
import LeanFM.Session.Syntax

/-- The shop as built: an API in front of a database. The database is not observable to the
client, so it belongs here, not in the requirements. -/
protocol ShopImpl (Client, Api, Db, Bank) {
  o: CreateOrder from Client to Api route "POST /orders";
  r: Reserve from Api to Db cause o;
  choice {
    v: Reserved from Db to Api cause r;
    q: Quote from Api to Client cause o status 201;
    p: Pay from Client to Api cause q;
    c: Charge from Api to Bank cause p;
    choice {
      d: Charged from Bank to Api cause c;
      w: RecordPayment from Api to Db cause d;
      k: Recorded from Db to Api cause w;
      Receipt from Api to Client cause d status 200;
    } or {
      x: Declined from Bank to Api cause c;
      ReleaseStock from Api to Db cause x;
      PaymentDeclined from Api to Client cause x status 402;
    }
  } or {
    n: OutOfStock from Db to Api cause r;
    SoldOut from Api to Client cause o status 409;
  }
}

implementation Go of examples.orders.Requirements {
  refines PlaceOrder by ShopImpl;
  "Orders are placed as PlaceOrder says" => conform "examples/orders/logs/order-1.json";
  "Every order is answered" => test "shop/order_test.go: TestEveryOrderAnswered";
  "Every payment is charged to the bank" => conform "examples/orders/logs/order-1.json";
  "No receipt without a charge" => sorry;
  "Stock is reserved before a quote" => ShopImpl ⊨ (not (EU (not (after Reserved)) (after Quote)));
  "A payment is recorded before the receipt" => ShopImpl ⊨ (not (EU (not (after Recorded)) (after Receipt)));
  hint "Implement the code as Go, with net/http and no web framework";
  hint "Keep orders in PostgreSQL; the Db role is one transaction per message";
}
